solution.jsx:
function MovieCard({ title, year, watched = false }) {
  return (
    <article>
      <h2>{title}</h2>
      <p>{year}</p>
      <p>{watched ? 'Watched' : 'To watch'}</p>
    </article>
  );
}

export default function App() {
  return (
    <main>
      <MovieCard title="Arrival" year={2016} watched />
      <MovieCard title="Past Lives" year={2023} />
      <MovieCard title="Paddington 2" year={2017} watched={false} />
    </main>
  );
}
